Translate("deDE", "ruins-of-lordaeron", {
	title = "Ruinen von Lordaeron",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Über {link:undercity}Undercity{/link} liegen die zerstörten Straßen der {link:capital-city}Hauptstadt{/link} Lordaerons. Die {link:forsaken}Verlassenen{/link} halten den Hof vor ihren Toren, doch jenseits davon ist ein großer Teil der alten Stadt noch in der Hand der {link:scourge}Geißel{/link}. Hirnlose Tote wandeln durch die Gassen, große Spinnen nisten in den Ruinen, und aus Gefallenen zusammengenähte Monstrositäten bewachen die Plätze. Seit Kurzem kriecht ein unheiliger Nebel über die Straßen und den alten Friedhof. Die Verlassenen sind hinaufgestiegen, um sich ihre Stadt zurückzuholen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Dies war die {link:capital-city}Hauptstadt{/link} von {link:lordaeron}Lordaeron{/link}, bis zu dem Tag, an dem Prinz {link:arthas-menethil}Arthas Menethil{/link} heimkehrte und seinen Vater ermordete. Die {link:scourge}Geißel{/link} plünderte die Stadt und schlachtete ihre Bewohner ab, und wer fiel, erhob sich wieder, um dem Lichkönig zu dienen. Als die Verlassenen sich befreiten, nahmen sie die Ruinen in Besitz und stiegen hinab, um {link:undercity}Undercity{/link} zu errichten. Sie hatten nicht die Kraft, die ganze zerstörte Stadt über ihnen zu säubern. Vor nicht langer Zeit zog die Nekropole {red:naxxramas}Naxxramas{/red} gegen die Stadt, und die Kämpfe tobten durch eben diese Straßen. Was die Geißel zurückließ, wurde nie beseitigt.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die Verlassenen kämpfen um ihre alten Straßen, einen Platz nach dem anderen. Sie verlieren Soldaten, die sie nicht ersetzen können, denn verwesendes Fleisch heilt nicht. Die Todeswache hat erfahren, dass der Nebel das Werk eines Nekromanten namens {link:rath-mael}Rath'mael{/link} ist, einer neuen Macht in den Reihen der {link:scourge}Geißel{/link}. Er scheint einen weiteren Angriff vorzubereiten. Die Apotheker von {link:undercity}Undercity{/link} wollen Proben der giftigen Bestien aus den Ruinen, und die Paladine der Verlassenen wollen die Gliedmaßen der Gefallenen, damit ihr Volk geflickt werden kann.]=],
		},
		{
			title = "In den Ruinen",
			text = [=[• {b}King's Alley.{/b} Nahe dem Eingang, wo eine große Spinne mit ihrer Brut jagt.
• {b}Market Street.{/b} Ein offener Platz der alten Stadt, wo sich die Toten in Wellen sammeln.
• {b}{link:lordaeron-graveyard}Lordaeron Graveyard{/link}.{/b} Der Friedhof der {link:capital-city}Hauptstadt{/link}, nun in Nebel gehüllt.
• {b}Lordamere Overlook.{/b} Tief in den Ruinen, wo {link:rath-mael}Rath'mael{/link} seine Magie wirkt.]=],
		},
		{
			title = "Relikte der Toten",
			text = [=[Die Ruinen sind voll von dem, was die Lebenden zurückließen. Abzeichen von Soldaten liegen im Schutt und warten noch immer auf die nächsten Angehörigen. Wappen des alten Königreichs tauchen zwischen den Steinen auf, und sowohl die Verlassenen als auch die Bewohner von {link:stormwind-city}Stormwind{/link} wollen sie um ihrer Geschichte willen. Auf dem Friedhof liegt der letzte Brief eines Verlassenen namens Edward Heartweaver. Er kam jede Woche hierher, um nach dem Leichnam seines Sohnes zu suchen, der verloren ging, als {link:arthas-menethil}Arthas{/link} die Stadt dem Erdboden gleichmachte. Er kehrte nicht zurück. Sein Sohn, so stellte sich heraus, hatte überlebt. Er wurde in ein Waisenhaus in Stormwind gebracht und ist seither von einer Frau in {link:duskwood}Dämmerwald{/link} adoptiert worden.]=],
		},
		{
			title = "Die hier hausen",
			text = [=[Die Spinne {link:witherfang}Witherfang{/link}, die Monstrosität namens {link:the-baron}der Baron{/link}, der Zurückgelassene, die Bestie {link:viktor-the-vile}Viktor der Abscheuliche{/link}, der Rohling {link:bjork}Bjork{/link} und der Nekromant {link:rath-mael}Rath'mael{/link} suchen die Ruinen heim. Der Geist eines Hauptmanns von {link:lordaeron}Lordaeron{/link} wird bisweilen unter ihnen gesehen. Ein Soldat der {link:alliance}Allianz{/link} namens Hauptmann Truman hält noch immer seinen Posten in den Ruinen und wartet auf einen Herrn, der sich vor einiger Zeit ins Getümmel stürzte und nicht zurückgekehrt ist.]=],
		},
	},
})

Translate("deDE", "lordaeron-graveyard", {
	title = "Lordaeron Graveyard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Lordaeron Graveyard war der Friedhof der {link:capital-city}Hauptstadt{/link}. Nun wandeln die Toten der zerstörten Stadt zwischen seinen zerbrochenen Steinen. Der Nebel, der sie verbirgt, ist hier am dichtesten, und Lebende wie {link:forsaken}Verlassene{/link} betreten ihn mit Vorsicht. Ein unheiliger Nebel liegt über dem Friedhof, heraufbeschworen von dem Nekromanten {link:rath-mael}Rath'mael{/link}. Manche Verlassene kommen noch immer hierher, um nach denen zu suchen, die sie verloren haben, und suchen auf den Steinen nach Namen, die sie im Leben kannten. Nicht alle von ihnen kehren zurück.]=],
		},
	},
})

